import{_ as t,o,c as d,a0 as a}from"./chunks/framework.l1I-fhud.js";const p=JSON.parse('{"title":"How to use the TUI","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/use-the-tui.md","filePath":"how-to/use-the-tui.md"}'),s={name:"how-to/use-the-tui.md"};function c(r,e,i,n,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="how-to-use-the-tui" tabindex="-1">How to use the TUI <a class="header-anchor" href="#how-to-use-the-tui" aria-label="Permalink to &quot;How to use the TUI&quot;">​</a></h1><p><code>tamias ui</code> opens an interactive console — the same operations as the CLI verbs, without memorizing flags. It needs the <code>tui</code> cargo feature (on by default; <code>cargo install tamias --no-default-features</code> builds the lean binary without it).</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ui</span></span></code></pre></div><h2 id="panes" tabindex="-1">Panes <a class="header-anchor" href="#panes" aria-label="Permalink to &quot;Panes&quot;">​</a></h2><p><code>Tab</code> / <code>1</code>–<code>5</code> switch between five panes:</p><ul><li><strong>Installed</strong> — every store entry: name, type, source ref, resolved sha, digest, size. <code>Enter</code> opens a detail view (manifest, provenance, provider services); <code>Esc</code>/<code>←</code> goes back.</li><li><strong>Registry</strong> — search-as-you-type against a registry (debounced; <code>Enter</code> fires immediately). <code>/</code> edits the query, <code>i</code> installs the selected result. <code>:registry &lt;name&gt;</code> picks the target — a configured registry name or a raw dir/http ref; bare <code>:registry</code> resets to the default routing.</li><li><strong>Services</strong> — installed packages&#39; <code>provider:</code> services with unit state. <code>s</code>/<code>S</code> start/stop, <code>r</code> restart, <code>e</code>/<code>E</code> enable/disable, <code>d</code> deploy, <code>x</code> uninstall (all confirmed). <code>t</code>/<code>T</code> tail/follow the journal, <code>n</code> runs the service in the foreground — <code>x</code> kills a live stream.</li><li><strong>Manifest</strong> — the project manifest&#39;s <code>deps:</code> as an editable table: <code>a</code> add a ref, <code>d</code>/<code>x</code> remove, <code>e</code> edit (installs the new ref, then swaps — a failed install leaves the manifest untouched). Writes go through the same manifest+lock path as <code>tamias add</code>.</li><li><strong>Author</strong> — <code>p</code> packs a payload dir (<code>bundle pack</code>), <code>P</code> publishes (dir + registry prompts, confirmed); <code>r</code> lists configured registries.</li></ul><h2 id="keys" tabindex="-1">Keys <a class="header-anchor" href="#keys" aria-label="Permalink to &quot;Keys&quot;">​</a></h2><p>Vim-style, same conventions as <code>myco ui</code>:</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>j</code>/<code>k</code>, arrows</td><td>move</td></tr><tr><td><code>/</code></td><td>filter (Installed) / query (Registry)</td></tr><tr><td><code>i</code></td><td>install-by-ref prompt (Installed) / install result (Registry)</td></tr><tr><td><code>v</code> <code>u</code> <code>U</code> <code>p</code> <code>r</code> <code>c</code> <code>C</code> <code>d</code></td><td>verify · update · update-all · pin · remove · cache clean (&gt;30d) · cache clean all · doctor</td></tr><tr><td><code>:</code></td><td>command line — <code>:install &lt;ref&gt;</code>, <code>:remove &lt;name&gt;</code>, <code>:verify</code>, <code>:update</code>, <code>:pin</code>, <code>:search &lt;q&gt;</code>, <code>:registry</code>, <code>:run</code>, <code>:logs</code>, <code>:service</code>, <code>:deploy</code>, <code>:manifest</code>, <code>:registries</code>, <code>:reload</code>, <code>:q</code></td></tr><tr><td><code>?</code></td><td>help overlay</td></tr><tr><td><code>R</code></td><td>reload</td></tr><tr><td><code>q</code> / <code>Ctrl-C</code></td><td>quit (kills any live service stream)</td></tr></tbody></table><p>Mutating verbs ask <code>y</code>/<code>n</code> first (default <code>n</code>). Installs that ship bundled <code>drivers/</code> raise the consent prompt — answering <code>y</code> is the equivalent of <code>--allow-drivers</code>; there is no env-var shortcut in the TUI.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Long ops (install, publish, verify) run on a worker thread; phases stream into the log strip with a spinner in the status bar.</li><li>The TUI watches the store root and reloads when it changes on disk — installs from other terminals show up without <code>R</code>.</li><li>Everything the TUI does is also available as CLI verbs or <code>tamias serve</code> ops — the TUI is a front-end, not a second engine.</li></ul>',12)])])}const g=t(s,[["render",c]]);export{p as __pageData,g as default};
